// ============================================================
// Widget "Ir al día de ayer": está pensado para colocarse en el estado
// "modificar_caudal_diario_hoy___copiar_1" (que se abre en un diálogo
// separado, con una entidad ya seleccionada). Al pulsar el botón:
//
//   1) Guarda en localStorage el rango de fechas de "ayer" (00:00:00 a
//      23:59:59.999 del día anterior al de hoy).
//   2) Dispara la acción configurada en la pestaña "Actions" de ESTE
//      widget (origen "click"), que debe ser del tipo nativo
//      "Navigate to dashboard state" apuntando al estado
//      "modificar_caudal_diario", con "Open state in a separate dialog"
//      y "Set entity from widget's datasource" activados. Así ThingsBoard
//      se encarga de abrir el diálogo nuevo con la misma entidad, que es
//      justo lo que ya hace de forma nativa y fiable -- este widget NO
//      reimplementa esa parte a mano.
//
// El estado de destino (modificar_caudal_diario) necesita, además, un
// pequeño fragmento de código en el onInit de alguno de sus widgets que
// lea ese localStorage y ajuste su ventana de tiempo -- eso va aparte,
// no es parte de este widget (un diálogo nuevo es un dashboard distinto,
// sin acceso directo al JS de este). Ver el mensaje donde se entregó este
// widget para el fragmento exacto a pegar allí.
//
// IMPORTANTE -- configuración necesaria, aparte de pegar este código:
//   a) En el EDITOR DEL TIPO DE WIDGET (aquí, donde pegas este código),
//      pestaña "Actions", hay que declarar un "Action source" con id
//      "click" (el nombre que le pongas da igual, el id es lo que
//      importa: debe ser exactamente "click", que es lo que usa este
//      controller.js más abajo).
//   b) Ya colocado el widget en el dashboard (dentro del estado
//      "modificar_caudal_diario_hoy___copiar_1"), en la configuración de
//      ESA INSTANCIA del widget aparecerá también una pestaña "Actions".
//      Ahí es donde se añade la acción real: origen "click", tipo
//      "Navigate to dashboard state", estado destino
//      "modificar_caudal_diario", con "Open state in a separate dialog"
//      y "Set entity from widget's datasource" ambos activados.
//   c) Este widget necesita tener configurada, en su pestaña "Data", la
//      misma entidad que ya está seleccionada en este estado (el mismo
//      alias que usan los demás widgets de "modificar_caudal_diario_hoy___copiar_1"),
//      para poder reenviarla al estado destino.
// ============================================================
self.onInit = function() {
    const $ctx = self.ctx;
    const $container = $ctx.$container;
    const $btn = $container.find('#iay-btn');

    // --- DIAGNÓSTICO TEMPORAL --------------------------------------
    // Muestra qué "action sources" tiene configurados de verdad este
    // widget (con sus acciones dentro), directamente desde la config
    // cruda, sin pasar por actionsApi.getActionDescriptors -- así vemos
    // el id real aunque no sea "click".
    try {
        const accionesCrudas = ($ctx.widgetConfig && $ctx.widgetConfig.actions) || {};
        console.log('[Ir a ayer] Action sources configurados en este widget:', Object.keys(accionesCrudas));
        console.log('[Ir a ayer] Contenido completo: ' + JSON.stringify(accionesCrudas));
    } catch (e) {
        console.error('[Ir a ayer] No se pudo leer $ctx.widgetConfig.actions:', e);
    }
    // -----------------------------------------------------------------

    const CLAVE_LOCALSTORAGE = 'riego_ventana_ayer';

    function calcularVentanaDeAyer() {
        const hoy = new Date();
        const inicioHoy = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate()).getTime();
        return {
            start: inicioHoy - 24 * 60 * 60 * 1000, // 00:00:00.000 de ayer
            end: inicioHoy - 1                       // 23:59:59.999 de ayer
        };
    }

    function guardarVentanaDeAyer() {
        const ventana = calcularVentanaDeAyer();
        try {
            localStorage.setItem(CLAVE_LOCALSTORAGE, JSON.stringify({
                start: ventana.start,
                end: ventana.end,
                creado: Date.now()
            }));
            return true;
        } catch (e) {
            console.error('[Ir a ayer] No se pudo guardar la ventana de tiempo en localStorage:', e);
            return false;
        }
    }

    function obtenerEntidadActual() {
        const datasources = $ctx.datasources || [];
        const ds = datasources.find(function(d) { return d.entityId; });
        if (!ds) { return { entityId: null, entityName: null }; }
        return {
            entityId: { id: ds.entityId, entityType: ds.entityType },
            entityName: ds.entityName
        };
    }

    $btn.on('click', function(event) {
        guardarVentanaDeAyer();

        const entidad = obtenerEntidadActual();
        if (!entidad.entityId) {
            console.warn('[Ir a ayer] Este widget no tiene ninguna entidad configurada en su pestaña "Datos" -- no se podrá reenviar la entidad al estado destino. Configura el mismo alias que usan los demás widgets de este estado.');
        }

        const descriptors = $ctx.actionsApi.getActionDescriptors('click');
        if (!descriptors || descriptors.length === 0) {
            console.error('[Ir a ayer] No hay ninguna acción configurada (origen "click") en la pestaña "Actions" de este widget. Añade una acción tipo "Navigate to dashboard state" hacia "modificar_caudal_diario", con "Open state in a separate dialog" y "Set entity from widget\'s datasource" activados.');
            return;
        }
        descriptors.forEach(function(descriptor) {
            $ctx.actionsApi.handleWidgetAction(event, descriptor, entidad.entityId, entidad.entityName);
        });
    });
};

self.onDestroy = function() {
    const $container = self.ctx.$container;
    $container.find('#iay-btn').off('click');
};

